package com.kitchenai.dashboard; import com.kitchenai.cooking.*; import com.kitchenai.recipe.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/dashboard") public class DashboardController { private final RecipeRepository recipes;private final CookingSessionRepository sessions; public DashboardController(RecipeRepository r,CookingSessionRepository s){recipes=r;sessions=s;} @GetMapping public Map<String,Object> dashboard(@AuthenticationPrincipal UUID id){return Map.of("recentRecipes",recipes.findTop10ByUserIdOrderByCreatedAtDesc(id),"recentSessions",sessions.findTop10ByUserIdOrderByStartedAtDesc(id),"progress",Map.of("totalXp",0,"level","BEGINNER_CHEF"));} @GetMapping("/recent-sessions") public List<CookingSession> recent(@AuthenticationPrincipal UUID id){return sessions.findTop10ByUserIdOrderByStartedAtDesc(id);}}
